import sample from "../public/data/daily.json";
import { lastNDays, listSources, parseDailyExport, summarize, toSeries } from "./data";

// The committed sample is generated by the Python pipeline; tests/test_dashboard_data.py
// keeps it in sync. These checks pin the cases the dashboard is meant to show.
describe("bundled synthetic sample", () => {
  const data = parseDailyExport(sample);
  const series = toSeries(data, "whoop");

  it("is four weeks of WHOOP data with no calendar gaps", () => {
    expect(listSources(data)).toEqual(["whoop"]);
    expect(series).toHaveLength(28);
    expect(series[0]?.day).toBe("2026-01-05");
    expect(series.at(-1)?.day).toBe("2026-02-01");
  });

  it("includes an unscorable recovery and an unfinished final cycle", () => {
    expect(series.find((p) => p.day === "2026-01-30")?.recovery).toBeNull();
    expect(series.at(-1)?.strain).toBeNull();
  });

  it("includes every recovery zone and some naps", () => {
    const scores = series.flatMap((p) => (p.recovery === null ? [] : [p.recovery]));
    expect(Math.min(...scores)).toBeLessThan(34);
    expect(Math.max(...scores)).toBeGreaterThanOrEqual(67);
    expect(series.some((p) => p.napCount > 0)).toBe(true);
  });

  it("summarises the last week", () => {
    expect(summarize(lastNDays(series, 7))).toMatchObject({
      days: 7,
      avgRecovery: 64,
      workouts: 5,
    });
  });
});
